idx = json.load(open("idxmap.json"))
lines = open("complex_opt2.xyz").read().splitlines()
n = int(lines[0])
atoms=[]
for l in lines[2:]:
    p=l.split(); atoms.append((p[0], float(p[1]), float(p[2]), float(p[3])))
pos = np.array([[a[1],a[2],a[3]] for a in atoms])
sym = [a[0] for a in atoms]
def d(i,j): return np.linalg.norm(pos[i]-pos[j])
# heavy-atom connectivity by distance
rcov = {'C':0.76,'H':0.31,'P':1.07,'Ir':1.32}
adj = {i:[] for i in range(n)}
for i in range(n):
    for j in range(i+1,n):
        if d(i,j) < rcov[sym[i]]+rcov[sym[j]]+0.35:
            adj[i].append(j); adj[j].append(i)
# find the 5-membered ring containing VL=23 among carbons
VL=23
# BFS for cycle: known ring C neighbors from graph
print("VL neighbors:", [(j,sym[j],round(d(VL,j),3)) for j in adj[VL]])
print("CQ=27 neighbors:", [(j,sym[j],round(d(27,j),3)) for j in adj[27]])
# ring C = the carbon 5-ring: find path VL-...-? using carbons only
carbons = [i for i in range(n) if sym[i]=='C']
# enumerate simple cycle of length 5 through VL within carbons
def find_cycle():
    # neighbors within carbon set
    nb = {i:[j for j in adj[i] if sym[j]=='C'] for i in carbons}
    for a in nb[VL]:
        for b in nb[a]:
            if b==VL: continue
            for c in nb[b]:
                if c in (VL,a): continue
                for e in nb[c]:
                    if e in (VL,a,b): continue
                    if VL in nb[e]:
                        return [VL,a,b,c,e]
    return None
cyc = find_cycle()
print("ring C cycle:", cyc)
if cyc:
    for i in range(5):
        a=cyc[i]; b=cyc[(i+1)%5]
        print(f"bond {a}-{b}: {round(d(a,b),3)}  (subs: {[(j,sym[j]) for j in adj[a] if j not in cyc]})")
# also check P connectivity
print("P neighbors:", [(j,sym[j],round(d(1,j),3)) for j in adj[1]])
print("Ir neighbors (within cov+0.35):", [(j,sym[j],round(d(86,j),3)) for j in adj[86]])
